//adds a list box to the UI
function AddListBox( in_layout, in_Name )
{
   // Insert a ListBox into the layout
   var oItem = in_layout.AddItem( in_Name, "", "ListBox" ) ;
   oItem.SetAttribute( siUIMultiSelectionListBox, true) ;
   oItem.setAttribute ("CY", 200);
}

//populates the list box with all the nulls in the scene
function AddNullsToList (in_layout, in_name, front, back, replace)
{
	nulls= new ActiveXObject("XSI.Collection");
	nulls.Items = ("MapRoot.*.null");
	var num = nulls.count;
  var listnulls = new Array( nulls.Count * 2 ) ;


	cutback = new String;
	//we know the scene always has "MapRoot" in it, so to get to the object name we need
  //to strip away MapRoot. and .null
	for (i=0; i<nulls.Count;i++)
	{
		bigname = new String(nulls(i));
		cutfront = new String (bigname.replace (front,replace));
		cutback = cutfront.replace (back,replace);
		listnulls[i*2] = cutback;
	listnulls[i*2 +1] = cutback;
	}
	var oItem = in_layout.Item(in_name);
  oItem.UIItems = listnulls;
}

/*--------------------------------------------------
		CompensateAxes_OnClicked
		
	// the following corrects the incorrect orientation of objects
	//	imported via import>vmf, and then converts them to XSI's local
	//	space (z=fwd, y=up).
	
	// it also adds a CustomParameter "HammerCompensation" to every
	//	compensated object, so that it's compensation status can be queried.
	// 
	// Only compensated objects will be written to the new vmf.	

------------------------------------------------------*/
function CompensateAxes_OnClicked()
{
for(i = 0;i < Selection.count; i++)
	{

		Osel = selection(i);
		
		try
		{
			var checkComp = GetValue(Osel+".HammerCompensation");
			t = XSIUIToolkit.Msgbox("\"CompensateAxes\" has already been applied to selection.\nNot gonna happen!");
			return
		}

		catch(e)
		{
		
	
			logmessage (Osel+" is being compensated");
			//logmessage (Osel);
			Orotx = GetValue(Osel+".kine.local.rotx", null);
			Oroty = GetValue(Osel+".kine.local.roty", null);
			//logmessage (Orotx);
			//logmessage (Oroty);
			SetValue(Osel+".kine.local.rotx",Oroty, null);
			SetValue(Osel+".kine.local.roty",Orotx, null);

			Rotate(Osel, 0, 90, 0, siRelative, siLocal, siObj, siXYZ, null, null, null, null, null, null, null, 0);
			Rotate(Osel, 0, 0, 90, siRelative, siLocal, siObj, siXYZ, null, null, null, null, null, null, null, 0);
	
			thisProp = Osel.AddProperty("CustomProperty",false, "HammerCompensation");
			//thisParam = thisProp.AddParameter3("isCompensated", siBool);	
			//SetValue(thisProp+".isCompensated", true);
			
		} // end catch
		
	} // end for

} // end function






/*------------------------
		ZeroMeOut_OnClicked
-------------------------*/
function ZeroMeOut_OnClicked()
{

	var oSel = selection(0);
	
	if (!oSel)
	{
		logmessage ("select what you want to be zeroed out");
		return
	}
	
	try
	{
		var checkComp = GetValue(Osel+".HammerCompensation");
		logmessage (checkComp);
	}

	catch(e)
	{
	t = XSIUIToolkit.Msgbox("\"CompensateAxes\" hasnt been applied to selection.\nFirst you must compensate the null you wish to be zeroed out");
	return
	}

	oMod = oSel.model;
	//logmessage (oMod);
	//logmessage (oSel);

	vecSel = XSIMath.CreateVector3();

	oSel.Kinematics.Global.Transform.GetTranslation(vecSel);

	vX = (vecSel.x);
	vY = (vecSel.y);
	vZ = (vecSel.z);


	Translate(oMod, vX*-1, vY*-1, vZ*-1, siRelative, siGlobal, siObj, siXYZ, null, null, null, null, null, null, null, null, null, 0);
	sceneRefresh();

	thisNull = GetPrim("Null");
	MatchTransform(thisNull, oSel, siSRT, null);

	ParentObj(thisNull, oMod);

	zeroNull = GetPrim("Null");
	MatchTransform(thisNull, zeroNull, siSRT, null);

	CutObj(oMod);
	DeleteObj(thisNull);
	DeleteObj(zeroNull);
	SelectObj(oSel);

} // end function



